export const records = [{"schema_version":1,"id":"AUT-0761","slug":"customer-subscription-common-end-date-alignment","title":"Узгодження спільної дати завершення підписок клієнта","summary":"Команда продажів погоджує групу підписок клієнта, допустиму дату завершення та перевіряє фактично застосований календар наступного періоду.","problem":"Додаткові підписки закінчуються в різні дні. Менеджер обіцяє спільне продовження, але змінює лише дату в CRM або плутає майбутній період із чинним.","outcome":"Клієнт має погоджений і перевірений календар продовження для вибраної групи; винятки й можливий коротший перший період залишаються видимими.","category":"sales-crm","subcategory":"customer-retention","roles":["sales-manager","operations-manager"],"industries":["cross-industry"],"triggers":["Клієнт замовляє додаткову підписку або погоджує спільний календар продовження кількох чинних підписок."],"workflow_steps":["Зібрати точні підписки клієнта, продавця, продукти, строки й поточні дати завершення; визначити групу, яку клієнт хоче узгодити.","Перевірити допустимість вирівнювання в джерелі підписок для кожного продукту та нового чи наступного періоду; недоступні позиції залишити окремими винятками.","Отримати допустиму цільову дату й умови можливого коротшого періоду; клієнт погоджує календар і наслідки до зміни.","Зберегти погоджену редакцію та звірити фактично заплановані зміни в джерелі; дату в CRM не видавати за змінений строк постачальника.","Після настання належного періоду прочитати фактичні дати всіх включених підписок; частково узгоджену групу не позначати завершеною.","Передати підтверджений календар у роботу продажів; перерахунок рахунків та оплату перевіряти окремим процесом без повторного застосування вже погодженої зміни."],"requirements":["Підписки одного клієнта з ідентифікаторами, продавцем і фактичними строками.","Підтверджені правила допустимих продуктів, дат і моменту застосування.","Погодження клієнта щодо складу групи, календаря та зміни першого періоду.","Доступ для читання фактичних і запланованих умов у джерелі підписок."],"limitations":["Microsoft описує вирівнювання для визначених ліцензійних підписок; це не універсальна функція будь-якого договору.","Для чинних підписок зміна стосується поновлення, а не довільного скорочення поточного строку. Допустимі дати й UTC перевіряють у джерелі.","Розрахунок допустимих дат має різне покриття в інтерфейсі та API; готовий адаптер не підтверджено.","Грошовий перерахунок, виставлення рахунків, заміну тарифу й примусове припинення послуг не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Додаткові підписки закінчуються в різні дні. Менеджер обіцяє спільне продовження, але змінює лише дату в CRM або плутає майбутній період із чинним."],"synonyms":["підписки клієнта завершуються в різні дні","менеджер обіцяв спільне продовження ліцензій","узгоджений календар поновлення не застосувався до всіх підписок"],"search_queries":["як узгодити спільну дату завершення кількох підписок клієнта і перевірити календар поновлення"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/partner-center/customers/align-subscription-end-dates","title":"Microsoft: узгодження дат завершення клієнтських підписок","checked_at":"2026-10-15","supports":"Прочитано 31–101: охоплення підписок, групи дат, новий і наступний періоди, UTC та різне покриття інтерфейсу й API. Погодження, звірка групи та години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"customer-subscription-common-end-date-alignment-tracked","title":"Контроль із підтвердженням результату","description":"Команда продажів погоджує групу підписок клієнта, допустиму дату завершення та перевіряє фактично застосований календар наступного періоду.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Клієнт погодив спільну дату для трьох ліцензійних підписок. У двох джерело показало належний наступний період, а третя позиція не підтримувала вибрані умови. Менеджер передав виняток на рішення, а не змінив лише дату в CRM.","implementation_methods":["Вести запит клієнта, склад групи, дозволені дати та докази фактичного поновлення.","Звіряти погоджений календар із джерелом підписок через перевірений доступ; невизначені результати передавати оператору."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Підписки одного клієнта з ідентифікаторами, продавцем і фактичними строками.","Підтверджені правила допустимих продуктів, дат і моменту застосування.","Погодження клієнта щодо складу групи, календаря та зміни першого періоду.","Доступ для читання фактичних і запланованих умов у джерелі підписок."],"limitations":["Microsoft описує вирівнювання для визначених ліцензійних підписок; це не універсальна функція будь-якого договору.","Для чинних підписок зміна стосується поновлення, а не довільного скорочення поточного строку. Допустимі дати й UTC перевіряють у джерелі.","Розрахунок допустимих дат має різне покриття в інтерфейсі та API; готовий адаптер не підтверджено.","Грошовий перерахунок, виставлення рахунків, заміну тарифу й примусове припинення послуг не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0013","reason":"Нагадування про продовження не узгоджує спільний календар групи підписок."},{"type":"related","target_id":"AUT-0133","reason":"Перерахунок оплати при зміні тарифу має окремі погодження й не підтверджує спільних дат групи."},{"type":"related","target_id":"AUT-0148","reason":"Запуск робіт за договором не змінює строки зовнішніх клієнтських підписок."},{"type":"related","target_id":"AUT-0658","reason":"Пауза чи відновлення підписки не є узгодженням дат завершення вибраної групи."}],"configurator_questions":[{"id":"customer-subscription-common-end-date-alignment-eligibility","question":"Чи потрібно перевіряти різні продукти й допустимі дати групи?","help_text":"Надайте перелік підписок, продавців, часову основу та правила сумісності строків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте перелік підписок, продавців, часову основу та правила сумісності строків."}]},{"id":"customer-subscription-common-end-date-alignment-renewal","question":"Чи потрібна звірка запланованої зміни після фактичного поновлення?","help_text":"Погодьте джерело стану, строк перевірки й маршрут часткового застосування.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте джерело стану, строк перевірки й маршрут часткового застосування."}]}]},{"schema_version":1,"id":"AUT-0762","slug":"publisher-advertiser-competitive-adjacency-control","title":"Контроль несумісного сусідства рекламодавців на майданчику","summary":"Видавець погоджує, які рекламодавці не мають з’являтися разом, перевіряє налаштування й розбирає фактичні порушення в потрібній області показу.","problem":"Видавець пообіцяв рекламодавцю відсутність конкурента поруч, але перелік заборон стосується іншої групи, місця або способу показу. Збережена позначка створює хибне підтвердження виконання.","outcome":"Є узгоджені правила рекламного сусідства, перевірене охоплення й докази розбору винятків; прогноз обсягу та факт заборони не підміняють один одного.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","sales-manager"],"industries":["cross-industry"],"triggers":["Погоджено обмеження на спільний показ реклами конкурентів або виявлено можливе порушення такого обмеження."],"workflow_steps":["Зафіксувати договірну обіцянку, сторони, період і область спільного показу: сторінку, місця чи відеоблок; загальне слово «ексклюзивність» уточнити.","Зіставити фактичні ідентифікатори рекламодавців, брендів і категорій із погодженими групами; перевірити режим заборони всередині групи або між групами.","Перевірити покриття типів угод, місць і способу рекламних запитів; недоступні випадки не включати в підтверджену обіцянку.","Уповноважений оператор застосовує погоджені правила; зберегти редакцію, успадкування позначок і дозволені винятки без мовчазного розширення заборони.","Звірити налаштування та погоджені приклади показу в потрібному контексті; один успішний приклад не вважати гарантією для всього трафіку.","За підозри на порушення зберегти час, місце, учасників і контекст запитів; передати на розбір, окремо переглянувши вплив заборони на проданий обсяг."],"requirements":["Точна погоджена обіцянка щодо спільного показу й її період.","Відповідність рекламодавців, брендів і категорій у рекламному сервері.","Перевірені права, типи угод, місця та спосіб рекламних запитів.","Дозволені приклади й дані показів для розбору можливих порушень."],"limitations":["Google Ad Manager описує різні режими конкурентних заборон; однакові назви груп не визначають їхню поведінку.","Для позначок конкурентного виключення документація описує технічні винятки; абсолютної гарантії всіх показів немає.","Кілька окремих рекламних запитів не гарантують потрібного виключення. Охоплення й успадкування треба перевіряти для фактичної реалізації.","Глобальний викуп усіх рекламних місць, розробку рекламного сервера й юридичне тлумачення ексклюзивності не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Видавець пообіцяв рекламодавцю відсутність конкурента поруч, але перелік заборон стосується іншої групи, місця або способу показу. Збережена позначка створює хибне підтвердження виконання."],"synonyms":["реклама конкурента з’явилася поруч із погодженим рекламодавцем","ексклюзивність розміщення не відповідає налаштуванням","заборона спільного показу працює для іншої групи рекламодавців"],"search_queries":["як контролювати заборону спільного показу реклами конкурентів на сторінці видавця"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/admanager/answer/6145371?hl=en","title":"Google Ad Manager: заборона спільного показу конкурентів","checked_at":"2026-10-15","supports":"Прочитано 17–78: групи, режими виключення й охоплення рекламного інвентарю. Обіцянки, докази й розбір — модель для аудиту."},{"type":"vendor_documentation","url":"https://support.google.com/admanager/answer/190582?hl=en","title":"Google Ad Manager: позначки конкурентного виключення","checked_at":"2026-10-15","supports":"Прочитано 17–56: успадкування, винятки, рекламні запити й вплив на доступний обсяг. Збережена позначка не доводить відсутності всіх порушень."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"publisher-advertiser-competitive-adjacency-control-tracked","title":"Контроль із підтвердженням результату","description":"Видавець погоджує, які рекламодавці не мають з’являтися разом, перевіряє налаштування й розбирає фактичні порушення в потрібній області показу.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Після скарги рекламодавця команда знайшла правильні позначки, але окремі запити місць на сторінці. Обіцянку не позначили виконаною: зберегли контекст, погодили виправлення й повторно перевірили потрібну область.","implementation_methods":["Вести погоджені обмеження, відповідність рекламодавців, перевірку охоплення та розбір інцидентів.","Звіряти редакцію правил із рекламним сервером і дозволеними доказами показів через перевірений маршрут."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Точна погоджена обіцянка щодо спільного показу й її період.","Відповідність рекламодавців, брендів і категорій у рекламному сервері.","Перевірені права, типи угод, місця та спосіб рекламних запитів.","Дозволені приклади й дані показів для розбору можливих порушень."],"limitations":["Google Ad Manager описує різні режими конкурентних заборон; однакові назви груп не визначають їхню поведінку.","Для позначок конкурентного виключення документація описує технічні винятки; абсолютної гарантії всіх показів немає.","Кілька окремих рекламних запитів не гарантують потрібного виключення. Охоплення й успадкування треба перевіряти для фактичної реалізації.","Глобальний викуп усіх рекламних місць, розробку рекламного сервера й юридичне тлумачення ексклюзивності не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0519","reason":"Відповідність майданчика бренду не визначає, які рекламодавці можуть показуватися поруч."},{"type":"related","target_id":"AUT-0669","reason":"Прогноз доступного інвентарю враховує обмеження, але не встановлює й не перевіряє обіцянку рекламного сусідства."},{"type":"related","target_id":"AUT-0672","reason":"Виконання кількості показів не доводить виконання заборони спільного показу конкурентів."},{"type":"related","target_id":"AUT-0638","reason":"Обіцяні спонсору місця заходу мають окремі докази; вони не перевіряють правила рекламного сервера."}],"configurator_questions":[{"id":"publisher-advertiser-competitive-adjacency-control-groups","question":"Чи потрібно звіряти кілька груп, брендів і винятків?","help_text":"Надайте погоджені правила, ідентифікатори та допустимі режими спільного показу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте погоджені правила, ідентифікатори та допустимі режими спільного показу."}]},{"id":"publisher-advertiser-competitive-adjacency-control-coverage","question":"Чи потрібна перевірка охоплення місць і способів рекламних запитів?","help_text":"Погодьте типи угод, приклади сторінок і маршрут розбору технічних винятків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Погодьте типи угод, приклади сторінок і маршрут розбору технічних винятків."}]}]},{"schema_version":1,"id":"AUT-0763","slug":"customer-subscription-partner-transfer-reconciliation","title":"Звірка передавання клієнтських підписок іншому партнеру","summary":"Команда узгоджує передавання визначених підписок між партнерами та підтверджує результат кожної позиції і зв’язок старих та нових записів.","problem":"Новий партнер прийняв клієнта, але запит ще не погоджено поточним партнером або передано лише частину підписок. Зміна відповідального в CRM приховує незавершені позиції.","outcome":"Відомо, які підписки фактично перейшли, де вони керуються й що залишилося невирішеним; повторний запит не дублює вже завершене передавання.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","operations-manager"],"industries":["cross-industry"],"triggers":["Клієнт і партнери погодили зміну партнера для конкретного переліку чинних підписок."],"workflow_steps":["Зафіксувати клієнта, поточного й нового партнерів, погоджений перелік підписок та умови передавання; перевірити ідентифікатори сторін і права.","Перевірити готовність нового партнерського зв’язку, допустимість продуктів і доступ нового партнера до потрібних пропозицій; згода клієнта не замінює потрібного погодження поточного партнера.","Зберегти фактичний запит передавання та зіставити вибрані поточним партнером позиції з погодженим переліком; розбіжності передати на рішення до виконання.","Відстежувати стан запиту й кожної позиції в джерелі; подання, прийняття та проміжний стан не вважати фактичним завершенням.","Після завершення звірити нові записи підписок, відповідність старим ідентифікаторам, істотні умови й заплановані зміни; невдалі позиції зберегти окремо.","За часткового результату погодити наступну дію лише для підтвердженого залишку; не створювати повторний запит, поки попередній ще обробляється.","Передати підтверджену відповідальність за керування послугами та докази; фінансові коригування й рахунки звіряти окремо від технічного результату."],"requirements":["Погоджений клієнтом і партнерами перелік підписок та сторін передавання.","Дозволені ідентифікатори, відомі умови й передумови нового партнерського зв’язку.","Авторитетний стан запиту, позицій та підписок обох сторін.","Погоджений порядок розбору часткового результату та залишку."],"limitations":["Microsoft описує конкретний процес передавання ліцензійних підписок між партнерами; інші продукти й сервіси потребують перевірки.","Запит може завершитися частково. Новий партнерський зв’язок сам по собі не передає чинні підписки.","Передавання може створювати нові ідентифікатори; історію не переписують лише заміною власника CRM.","Створення міграційного сервісу, перенесення даних користувачів, реальні партнерські операції та розрахункове проведення не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Новий партнер прийняв клієнта, але запит ще не погоджено поточним партнером або передано лише частину підписок. Зміна відповідального в CRM приховує незавершені позиції."],"synonyms":["клієнт перейшов до нового партнера але підписки лишилися у старого","частина підписок не передалася новому партнеру","погоджений перелік ліцензій не збігається з результатом передавання"],"search_queries":["як звіряти передавання клієнтських підписок між партнерами частковий результат і нові ідентифікатори"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/partner-center/customers/transfer-new-commerce-license-based-subscriptions","title":"Microsoft: передавання клієнтських ліцензійних підписок між партнерами","checked_at":"2026-10-15","supports":"Прочитано 31–130; повторно звірено 39–105: двосторонній запит, позиції, часткове завершення й нові ідентифікатори. Погодження, звірка та години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"customer-subscription-partner-transfer-reconciliation-tracked","title":"Контроль із підтвердженням результату","description":"Команда узгоджує передавання визначених підписок між партнерами та підтверджує результат кожної позиції і зв’язок старих та нових записів.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Поточний партнер подав п’ять погоджених підписок. Чотири завершили передавання, п’ята залишилася невдалою. Команда звірила нові записи й погодила повторне опрацювання лише залишку після завершення попереднього запиту.","implementation_methods":["Вести погоджений перелік, запит, стани позицій, відповідність старих і нових записів та невирішений залишок.","Звіряти результати авторитетного сервісу через перевірений доступ; події без повного стану передавати на уточнення."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Погоджений клієнтом і партнерами перелік підписок та сторін передавання.","Дозволені ідентифікатори, відомі умови й передумови нового партнерського зв’язку.","Авторитетний стан запиту, позицій та підписок обох сторін.","Погоджений порядок розбору часткового результату та залишку."],"limitations":["Microsoft описує конкретний процес передавання ліцензійних підписок між партнерами; інші продукти й сервіси потребують перевірки.","Запит може завершитися частково. Новий партнерський зв’язок сам по собі не передає чинні підписки.","Передавання може створювати нові ідентифікатори; історію не переписують лише заміною власника CRM.","Створення міграційного сервісу, перенесення даних користувачів, реальні партнерські операції та розрахункове проведення не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0547","reason":"Внутрішня зміна менеджера CRM не передає підписки між зовнішніми партнерами."},{"type":"related","target_id":"AUT-0695","reason":"Припинення торгового зв’язку не створює нові підписки іншого партнера й не підтверджує їхні умови."},{"type":"related","target_id":"AUT-0286","reason":"Перенесення домену має інший об’єкт, підтвердження й залежності."},{"type":"related","target_id":"AUT-0761","reason":"Спільний календар завершення підписок не змінює партнера, який ними керує."}],"configurator_questions":[{"id":"customer-subscription-partner-transfer-reconciliation-scope","question":"Чи потрібно звіряти перелік і умови багатьох позицій передавання?","help_text":"Надайте погоджений склад, істотні умови та правила зіставлення старих і нових записів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте погоджений склад, істотні умови та правила зіставлення старих і нових записів."}]},{"id":"customer-subscription-partner-transfer-reconciliation-partial","question":"Чи потрібен контроль часткового завершення й залишку повторного запиту?","help_text":"Погодьте джерело стану, момент завершення обробки та дозволений маршрут невдалих позицій.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Погодьте джерело стану, момент завершення обробки та дозволений маршрут невдалих позицій."}]}]},{"schema_version":1,"id":"AUT-0764","slug":"production-model-prediction-actual-outcome-quality-review","title":"Перевірка якості робочих прогнозів моделі за фактичними результатами","summary":"Команда зіставляє збережені прогнози робочої моделі з пізніше отриманими результатами та погоджує дію за перевіреною якістю.","problem":"Зміни вхідних даних не показують, скільки прогнозів справді помилкові. Неповні фактичні результати або хибне зіставлення записів створюють оманливу оцінку якості.","outcome":"Є відтворювана оцінка для конкретної моделі й періоду, видимі неповні зіставлення та погоджена дія без автоматичного перенавчання за неперевіреним сигналом.","category":"ai-knowledge-work","subcategory":"classification","roles":["operations-manager","owner"],"industries":["cross-industry"],"triggers":["Для збережених прогнозів робочої моделі надійшли фактичні результати або настав погоджений строк їх перевірки."],"workflow_steps":["Зафіксувати версію моделі, період прогнозів, значення виходу, унікальні ідентифікатори й погоджені правила оцінки; не змішувати різні розгортання.","Отримати дозволені фактичні результати з відомим часом актуальності; відсутній результат не вважати негативною міткою.","Зіставити прогноз і факт за перевіреним ключем кожного випадку; пропуски, повтори й неоднозначні відповідності винести в окрему чергу.","Погодити достатність і зрілість зіставленої вибірки; запізнілі результати та різне охоплення не приховувати високою середньою оцінкою.","Розрахувати погоджені показники якості для зіставних даних і зберегти склад вибірки, редакції факту й пороги; відокремити збій збору від погіршення прогнозів.","Власник розглядає відхилення та погоджує бізнес-дію або повторний вимір; сигнал не запускає самостійне перенавчання чи заміну робочої моделі.","Після виправлення або пізнього надходження фактів створити нову редакцію оцінки; звірити виконання погодженої дії без стирання попереднього висновку."],"requirements":["Збережені прогнози з версією моделі та унікальним ключем кожного випадку.","Авторитетні фактичні результати з відповідними ключами й дозволеним використанням.","Правила зрілості вибірки, запізнення фактів, метрик і допустимих відхилень.","Власник бізнес-рішення та погоджений маршрут перегляду якості."],"limitations":["Azure Machine Learning вимагає фактичних результатів і відповідних ідентифікаторів; без них оцінка точності робочих прогнозів не підтверджена.","Якість за зіставленою частиною не описує автоматично випадки, для яких факту немає; вибіркове надходження результатів потребує перегляду.","Розглянуто табличні класифікаційні й регресійні моделі; показники не переносять без перевірки на відповіді генеративного ШІ.","Створення джерела фактичних міток, навчання моделі, великі обчислення та автоматичне перемикання сервісу не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Зміни вхідних даних не показують, скільки прогнозів справді помилкові. Неповні фактичні результати або хибне зіставлення записів створюють оманливу оцінку якості."],"synonyms":["немає фактичних результатів для перевірки точності моделі","прогнози моделі неправильно поєднали з реальними наслідками","пізні результати змінили висновок про якість робочої моделі"],"search_queries":["як перевіряти якість робочої моделі зіставивши прогнози з фактичними результатами за ключами випадків"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/azure/machine-learning/how-to-monitor-model-performance?view=azureml-api-2","title":"Microsoft: перевірка якості робочої моделі за фактичними результатами","checked_at":"2026-10-15","supports":"Прочитано 624–665: вихідні прогнози, фактичні результати, відповідні ключі та особливість рядків пакетного збору. Зрілість вибірки, рішення та години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"production-model-prediction-actual-outcome-quality-review-tracked","title":"Контроль із підтвердженням результату","description":"Команда зіставляє збережені прогнози робочої моделі з пізніше отриманими результатами та погоджує дію за перевіреною якістю.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Для 800 прогнозів з’явилося лише 300 фактичних результатів, а частина ключів повторювалася. Команда не заявила загальну точність: відокремила неповні зіставлення й сформувала нову оцінку після виправлення.","implementation_methods":["Вести періоди перевірки, редакції прогнозів і фактів, пропуски зіставлення та рішення за якістю.","Отримувати дозволені знімки або результати моніторингу через перевірений маршрут; приватні приклади залишати в погодженому сховищі."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Збережені прогнози з версією моделі та унікальним ключем кожного випадку.","Авторитетні фактичні результати з відповідними ключами й дозволеним використанням.","Правила зрілості вибірки, запізнення фактів, метрик і допустимих відхилень.","Власник бізнес-рішення та погоджений маршрут перегляду якості."],"limitations":["Azure Machine Learning вимагає фактичних результатів і відповідних ідентифікаторів; без них оцінка точності робочих прогнозів не підтверджена.","Якість за зіставленою частиною не описує автоматично випадки, для яких факту немає; вибіркове надходження результатів потребує перегляду.","Розглянуто табличні класифікаційні й регресійні моделі; показники не переносять без перевірки на відповіді генеративного ШІ.","Створення джерела фактичних міток, навчання моделі, великі обчислення та автоматичне перемикання сервісу не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0318","reason":"Порівняння кандидатів на контрольному наборі перед запуском не оцінює фактичних робочих прогнозів після надходження результатів."},{"type":"related","target_id":"AUT-0696","reason":"Зміна розподілу вхідних ознак не доводить зміни точності; потрібні зіставлені фактичні результати."},{"type":"related","target_id":"AUT-0341","reason":"Погодження людської розмітки допомагає підготувати факт, але не зіставляє його з робочими прогнозами."},{"type":"related","target_id":"AUT-0410","reason":"Фінансовий прогноз порівнюють за рахунками й періодами; тут контролюють окремі передбачення, фактичні мітки та версію ML-моделі."}],"configurator_questions":[{"id":"production-model-prediction-actual-outcome-quality-review-joining","question":"Чи потрібно звіряти ключі прогнозів і фактів із різних джерел?","help_text":"Надайте схеми ключів, версії моделі, порядок пакетних рядків та правила неоднозначних відповідностей.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте схеми ключів, версії моделі, порядок пакетних рядків та правила неоднозначних відповідностей."}]},{"id":"production-model-prediction-actual-outcome-quality-review-late","question":"Чи потрібні повторні оцінки після запізнілих або виправлених фактів?","help_text":"Погодьте зрілість вибірки, строки, історію редакцій та маршрут зміни попереднього висновку.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте зрілість вибірки, строки, історію редакцій та маршрут зміни попереднього висновку."}]}]},{"schema_version":1,"id":"AUT-0765","slug":"former-employee-rehire-history-reconciliation","title":"Звірка повторного найму з попередньою кадровою історією","summary":"HR пов’язує повернення колишнього працівника з перевіреним кадровим записом та звіряє нове оформлення без втрати попередньої історії.","problem":"Колишнього працівника оформлюють як незнайому особу або без перевірки відновлюють старі умови. Кадрова історія розривається, а дані попереднього працевлаштування стають доступні зайвим людям.","outcome":"Є підтверджена особа, погоджений спосіб повторного оформлення та зв’язок кадрових періодів; старі умови й доступи не відновлюються без власних рішень.","category":"hr","subcategory":"onboarding","roles":["hr-specialist","operations-manager"],"industries":["cross-industry"],"triggers":["Погоджено повернення до компанії людини, яка вже мала завершене працевлаштування."],"workflow_steps":["Ідентифікувати людину й попередні кадрові записи за дозволеними доказами; збіг імені не вважати достатнім підтвердженням.","Звірити фактичний стан і дату завершення попереднього працевлаштування, юридичну особу та погоджену дату нового виходу; невизначені періоди передати HR.","Уповноважений кадровий відповідальний визначає допустимий спосіб оформлення й зв’язок історії; не відновлювати старий запис лише зміною статусу.","Погодити актуальні особисті дані, посаду й умови нового періоду та межі перегляду попередньої історії; застарілі реквізити не переносити мовчки.","Після дозволеного оформлення прочитати фактичні ідентифікатори, період і призначення; перевірити відсутність непогодженого дубля чи накладення.","Передати перевірений новий період на адаптацію й потрібні кадрові процеси; оплату, пільги та доступи застосовувати лише за окремими погодженнями.","Зберегти доказ зв’язку старої й нової історії та невирішені винятки; перенесення дати повернути на перевірку без переписування минулих періодів."],"requirements":["Підтверджена особа та дозволений доступ до попередньої кадрової історії.","Погоджені дата, юридична особа, посада та умови нового періоду.","Перевірені правила повторного оформлення й зіставлення ідентифікаторів у цільовій HR-системі.","Власник кадрового рішення та окремі маршрути оплати, пільг і доступів."],"limitations":["SAP у сценарії 2405 описує повторний найм із попереднім ідентифікатором особи та передумовами; це не гарантує такої поведінки іншої HR-системи.","Новий період не доводить автоматичного відновлення стажу, виплат, пільг або попередніх доступів.","Історичний тестовий сценарій не підтверджує актуальних прав і налаштувань конкретного акаунта.","Трудові рішення, юридичне поновлення, розрахунок виплат і повну міграцію HR-системи не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Колишнього працівника оформлюють як незнайому особу або без перевірки відновлюють старі умови. Кадрова історія розривається, а дані попереднього працевлаштування стають доступні зайвим людям."],"synonyms":["колишнього працівника створили вдруге без зв’язку з кадровою історією","під час повернення працівника перенесли застарілі умови","повторний найм розірвав попередні кадрові періоди"],"search_queries":["як оформити повторний найм колишнього працівника зі звіркою попередньої кадрової історії"],"sources":[{"type":"vendor_documentation","url":"https://help.sap.com/doc/ba8f9528d79f1c06586d20afe2027b14/2405/en-US/Manage_Hire_Rehire_Test_Script_FJ0.pdf","title":"SAP: сценарій повторного найму працівника, редакція 2405","checked_at":"2026-10-15","supports":"Розділ 4.2.1, друковані сторінки 103–105, рядки 4162–4239: наявна історія особи та передумови повторного найму. Погодження, звірка й години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"former-employee-rehire-history-reconciliation-tracked","title":"Контроль із підтвердженням результату","description":"HR пов’язує повернення колишнього працівника з перевіреним кадровим записом та звіряє нове оформлення без втрати попередньої історії.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Для людини, яка повертається, знайшли попередній кадровий запис, але адреса й підрозділ застаріли. HR погодив актуальні умови та звірив новий період; старі доступи не відновлювали автоматично.","implementation_methods":["Вести справу повторного найму з посиланнями на дозволені кадрові записи, погоджені умови та результати звірки.","Зіставляти періоди й ідентифікатори з авторитетною HR-системою через перевірений доступ; чутливі документи залишати в захищеному сховищі."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Підтверджена особа та дозволений доступ до попередньої кадрової історії.","Погоджені дата, юридична особа, посада та умови нового періоду.","Перевірені правила повторного оформлення й зіставлення ідентифікаторів у цільовій HR-системі.","Власник кадрового рішення та окремі маршрути оплати, пільг і доступів."],"limitations":["SAP у сценарії 2405 описує повторний найм із попереднім ідентифікатором особи та передумовами; це не гарантує такої поведінки іншої HR-системи.","Новий період не доводить автоматичного відновлення стажу, виплат, пільг або попередніх доступів.","Історичний тестовий сценарій не підтверджує актуальних прав і налаштувань конкретного акаунта.","Трудові рішення, юридичне поновлення, розрахунок виплат і повну міграцію HR-системи не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0042","reason":"Адаптація готує вихід на роботу, але не визначає зв’язок повторного найму з попереднім кадровим періодом."},{"type":"related","target_id":"AUT-0079","reason":"Завершення роботи закриває попередній період; саме по собі не підтверджує нового оформлення."},{"type":"related","target_id":"AUT-0185","reason":"Переведення чинного працівника не є повторним наймом після завершення працевлаштування."},{"type":"related","target_id":"AUT-0169","reason":"Прийнята пропозиція роботи не доводить правильно оформленої кадрової історії."}],"configurator_questions":[{"id":"former-employee-rehire-history-reconciliation-history","question":"Чи потрібно звіряти кілька попередніх записів і способів повторного оформлення?","help_text":"Надайте правила ідентифікації, періодів, юридичних осіб і допустимих варіантів HR-системи.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте правила ідентифікації, періодів, юридичних осіб і допустимих варіантів HR-системи."}]},{"id":"former-employee-rehire-history-reconciliation-handoff","question":"Чи потрібна перевірка передавання нового періоду в пов’язані кадрові процеси?","help_text":"Погодьте системи, відповідальних і межі доступу до попередньої історії.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте системи, відповідальних і межі доступу до попередньої історії."}]}]},{"schema_version":1,"id":"AUT-0766","slug":"employee-first-day-no-show-record-reconciliation","title":"Опрацювання неявки працівника в перший робочий день","summary":"Керівник і HR уточнюють фактичний вихід новоприйнятого працівника та перевіряють погоджене кадрове оформлення й пов’язані процеси.","problem":"Працівник уже є в кадровій системі, але не вийшов у погоджений перший день. Незавершена задача адаптації або пропущена відмітка помилково запускає кадрові зміни чи залишає суперечливий активний запис.","outcome":"Є перевірені факти й рішення уповноваженого HR; кадровий стан і наступні процеси відповідають погодженому результату, а помилкова неявка повертається на уточнення.","category":"hr","subcategory":"onboarding","roles":["hr-specialist","operations-manager"],"industries":["cross-industry"],"triggers":["У перший погоджений робочий день керівник не підтвердив фактичного виходу вже оформленого працівника."],"workflow_steps":["Пов’язати людину, точний кадровий період, погоджену дату та керівника; перевірити перенесення виходу й незавершені зміни дати.","Зібрати підтвердження керівника та дозволені відомості про зв’язок із працівником; пропущений запис присутності не прирівнювати до доведеної неявки.","HR розглядає факти й визначає застосовний кадровий маршрут за чинною політикою; очікування уточнення відокремити від погодженого оформлення.","Уповноважений виконавець вносить лише погоджену дію в HR-системі; перевірити особу, період, дату й підставу до підтвердження.","Прочитати фактичний кадровий результат і перевірити вплив на позицію, заплановані задачі та передачі в пов’язані системи; невизначений результат не повторювати сліпо.","За помилкового повідомлення або пізнього підтвердження виходу повернути справу HR для окремого виправлення; не переписувати первинні докази.","Закрити контроль після перевіреного рішення й передавання відкритих кадрових або розрахункових питань відповідальним; повідомлення керівника не вважати завершенням усіх систем."],"requirements":["Погоджена дата виходу й точний ідентифікатор кадрового періоду.","Перевірені факти керівника та дозволений маршрут уточнення з працівником.","Уповноважений HR і застосовна кадрова політика без автоматичного правового висновку.","Джерело фактичного кадрового стану та список залежних процесів."],"limitations":["SAP у сценарії 2405 описує повідомлення керівника та кадрове погодження неявки; конкретні строки й стани перевіряють у цільовій системі.","Наявність функції в програмі не визначає правових наслідків неявки, законності припинення або обов’язку виплати.","Автоматизація не робить висновку про прогул лише через відсутню відмітку та не скасовує працевлаштування без кадрового рішення.","Юридичне оформлення, зарплатний розрахунок, відновлення доступів і спори з працівником не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Працівник уже є в кадровій системі, але не вийшов у погоджений перший день. Незавершена задача адаптації або пропущена відмітка помилково запускає кадрові зміни чи залишає суперечливий активний запис."],"synonyms":["новоприйнятий працівник не вийшов у перший день","кадровий запис залишився активним після непідтвердженого виходу","помилково повідомили про неявку нового працівника"],"search_queries":["як погоджувати неявку працівника в перший робочий день і звіряти кадровий запис"],"sources":[{"type":"vendor_documentation","url":"https://help.sap.com/doc/ba8f9528d79f1c06586d20afe2027b14/2405/en-US/Manage_Hire_Rehire_Test_Script_FJ0.pdf","title":"SAP: повідомлення й кадрове погодження неявки в перший день, редакція 2405","checked_at":"2026-10-15","supports":"Прочитано вибрані основні фрагменти 4.1.6, друковані сторінки 93–100: повідомлення, кадрове погодження, повернення помилкової дії та перевірка результату. Власні звірки й години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"employee-first-day-no-show-record-reconciliation-tracked","title":"Контроль із підтвердженням результату","description":"Керівник і HR уточнюють фактичний вихід новоприйнятого працівника та перевіряють погоджене кадрове оформлення й пов’язані процеси.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Керівник не побачив працівника на місці, але HR знайшов погоджене перенесення дати. Справу повернули на уточнення замість автоматичної зміни кадрового стану; задачу підготовки скоригували за підтвердженою датою.","implementation_methods":["Вести повідомлення, підтвердження факту, кадрове рішення та докази стану потрібного періоду.","Звіряти результат авторитетної HR-системи й погоджені наступні дії; розрахункові та правові питання передавати відповідальним."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Погоджена дата виходу й точний ідентифікатор кадрового періоду.","Перевірені факти керівника та дозволений маршрут уточнення з працівником.","Уповноважений HR і застосовна кадрова політика без автоматичного правового висновку.","Джерело фактичного кадрового стану та список залежних процесів."],"limitations":["SAP у сценарії 2405 описує повідомлення керівника та кадрове погодження неявки; конкретні строки й стани перевіряють у цільовій системі.","Наявність функції в програмі не визначає правових наслідків неявки, законності припинення або обов’язку виплати.","Автоматизація не робить висновку про прогул лише через відсутню відмітку та не скасовує працевлаштування без кадрового рішення.","Юридичне оформлення, зарплатний розрахунок, відновлення доступів і спори з працівником не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0042","reason":"Готовність до першого дня не підтверджує фактичного виходу й погодженої кадрової дії."},{"type":"related","target_id":"AUT-0138","reason":"Виправлення відмітки присутності не визначає кадрового стану нового періоду працевлаштування."},{"type":"related","target_id":"AUT-0079","reason":"Завершення роботи чинного працівника не замінює розгляд факту першого виходу."},{"type":"related","target_id":"AUT-0169","reason":"Прийняття пропозиції не доводить, що людина фактично почала роботу."}],"configurator_questions":[{"id":"employee-first-day-no-show-record-reconciliation-evidence","question":"Чи потрібна перевірка змін дати та фактів із кількох джерел?","help_text":"Погодьте джерела дати, керівника, доказів виходу та маршрут суперечливих повідомлень.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте джерела дати, керівника, доказів виходу та маршрут суперечливих повідомлень."}]},{"id":"employee-first-day-no-show-record-reconciliation-downstream","question":"Чи потрібно звіряти залежні процеси після кадрового рішення?","help_text":"Надайте перелік пов’язаних систем, позицій і задач; визначте дозволені дії та підтвердження.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте перелік пов’язаних систем, позицій і задач; визначте дозволені дії та підтвердження."}]}]},{"schema_version":1,"id":"AUT-0767","slug":"employee-concurrent-employment-records-control","title":"Контроль одночасних працевлаштувань одного працівника","summary":"HR звіряє кілька чинних працевлаштувань тієї самої людини, їхні ідентифікатори та основне призначення без закриття потрібних записів.","problem":"Додаткове працевлаштування створюють як іншу людину або помилково замінюють ним чинне. При завершенні одного призначення припиняють усі записи чи залишають неоднозначне основне працевлаштування.","outcome":"Для людини видно погоджені чинні призначення, основне працевлаштування й результати кожної зміни; оплата та доступи не змішуються лише через спільний профіль.","category":"hr","subcategory":"workforce","roles":["hr-specialist","operations-manager"],"industries":["cross-industry"],"triggers":["Погоджено додаткове одночасне працевлаштування або зміну складу вже чинних працевлаштувань однієї людини."],"workflow_steps":["Пов’язати підтверджену особу з усіма чинними й запланованими кадровими призначеннями; окремо зберегти ключ особи та ключ кожного працевлаштування.","Перевірити допустимість одночасного оформлення, дати, юридичні особи й обмеження системи; не трактувати подію як завершення попереднього періоду.","HR погоджує конкретні умови додаткового призначення та основне працевлаштування; навантаження й залежні кадрові правила перевіряють за затвердженою політикою.","Після дозволеної дії прочитати фактичний новий запис і стан чинних призначень; схожий профіль або однакове ім’я не доводять правильного зв’язку.","Звірити контекст передавання в оплату, відпустки й керування доступом; події одного призначення не застосовувати автоматично до решти.","При завершенні одного призначення перевірити погоджену область дії та основне працевлаштування серед залишку; завершення особи загалом потребує окремої підстави.","Зберегти історію й результати кожного призначення; зміну дати або частково застосовану дію повернути на звірку без сліпого повтору."],"requirements":["Перевірена відповідність особи й кожного кадрового призначення.","Погоджені підстави, дати, умови та правила основного працевлаштування.","Підтверджена підтримка одночасних працевлаштувань у цільовій HR-системі.","Власники залежних процесів, доступні результати й межі використання кадрових даних."],"limitations":["SAP у редакції 2605 розрізняє особу й окремі працевлаштування; інша система може мати іншу модель ідентифікаторів.","Єдине основне призначення в програмі не визначає правового статусу роботи або загального дозволеного навантаження.","Облік часу та відпусток різних призначень не можна вважати автоматично спільним; потрібна перевірка конкретного процесу.","Правову допустимість сумісництва, зарплатний розрахунок, нові доступи та повне впровадження HR-системи не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Додаткове працевлаштування створюють як іншу людину або помилково замінюють ним чинне. При завершенні одного призначення припиняють усі записи чи залишають неоднозначне основне працевлаштування."],"synonyms":["додаткове працевлаштування помилково закрило основне","одну людину створили як різних працівників при одночасній роботі","завершення одного призначення вимкнуло решту працевлаштувань"],"search_queries":["як контролювати одночасні працевлаштування однієї людини основне призначення і завершення окремого запису"],"sources":[{"type":"vendor_documentation","url":"https://help.sap.com/doc/cc751d98800d414ca72fc4695a9bf3e7/2605/en-US/SF_EC_Master_Impl.pdf","title":"SAP: одночасні працевлаштування, редакція 2605","checked_at":"2026-10-15","supports":"Локально прочитано сторінки 848–853 і 859–860: особа й записи працевлаштувань, основне призначення, додавання та область завершення. Власні погодження, звірки й години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"employee-concurrent-employment-records-control-tracked","title":"Контроль із підтвердженням результату","description":"HR звіряє кілька чинних працевлаштувань тієї самої людини, їхні ідентифікатори та основне призначення без закриття потрібних записів.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Працівнику погодили друге призначення. HR звірив новий кадровий ключ із тією самою особою та збереження чинного періоду. Після завершення другого призначення перевірили, що основне продовжує діяти.","implementation_methods":["Вести погоджені події, зв’язки особи й призначень, основний контекст та перевірені результати.","Звіряти конкретне працевлаштування з авторитетною HR-системою; приватні документи й секрети не копіювати в загальні задачі."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Перевірена відповідність особи й кожного кадрового призначення.","Погоджені підстави, дати, умови та правила основного працевлаштування.","Підтверджена підтримка одночасних працевлаштувань у цільовій HR-системі.","Власники залежних процесів, доступні результати й межі використання кадрових даних."],"limitations":["SAP у редакції 2605 розрізняє особу й окремі працевлаштування; інша система може мати іншу модель ідентифікаторів.","Єдине основне призначення в програмі не визначає правового статусу роботи або загального дозволеного навантаження.","Облік часу та відпусток різних призначень не можна вважати автоматично спільним; потрібна перевірка конкретного процесу.","Правову допустимість сумісництва, зарплатний розрахунок, нові доступи та повне впровадження HR-системи не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0185","reason":"Переведення змінює чинне призначення; додаткове одночасне працевлаштування має зберігати потрібні чинні записи."},{"type":"related","target_id":"AUT-0765","reason":"Повторний найм після завершеного періоду не охоплює кілька одночасно чинних працевлаштувань."},{"type":"related","target_id":"AUT-0042","reason":"Адаптація не визначає відповідність особи та кількох кадрових записів."},{"type":"related","target_id":"AUT-0040","reason":"Планування задач і доступних годин не оформлює кілька працевлаштувань і не визначає їхній кадровий контекст."}],"configurator_questions":[{"id":"employee-concurrent-employment-records-control-assignments","question":"Чи потрібно звіряти кілька призначень і правила основного працевлаштування?","help_text":"Надайте модель ідентифікаторів, дати, обмеження та погоджені кадрові правила.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте модель ідентифікаторів, дати, обмеження та погоджені кадрові правила."}]},{"id":"employee-concurrent-employment-records-control-downstream","question":"Чи потрібна перевірка впливу окремої зміни на залежні процеси?","help_text":"Погодьте контексти оплати, відпусток і доступів та докази стану решти призначень.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте контексти оплати, відпусток і доступів та докази стану решти призначень."}]}]},{"schema_version":1,"id":"AUT-0768","slug":"internal-organization-hierarchy-version-release-control","title":"Введення нової редакції внутрішньої організаційної ієрархії","summary":"Власник організаційної моделі погоджує зміну внутрішньої ієрархії, дату дії та перевіряє застосування редакції у визначених залежних процесах.","problem":"Підрозділи вже перемістили на схемі, але робочі політики або звіти використовують стару ієрархію чи інше її призначення. Чернетку помилково вважають чинною структурою.","outcome":"Є погоджена редакція з датою дії, відома область застосування й результати перевірки залежних правил; історичні операції не переписують лише через нову структуру.","category":"management-analytics","subcategory":"planning","roles":["owner","operations-manager"],"industries":["cross-industry"],"triggers":["Погоджено зміну внутрішніх організаційних зв’язків, яка має застосовуватися з визначеної дати в робочих політиках або звітності."],"workflow_steps":["Зафіксувати чинну ієрархію, її призначення, вузли, дату зміни й власника; організаційну одиницю не прирівнювати автоматично до юридичної особи.","Підготувати чернетку нової редакції з точними додаваннями, переміщеннями й виключеннями; перевірити потрібні вузли, однозначність зв’язків та область застосування.","Визначити політики, маршрути й звіти, які фактично використовують цю ієрархію; оцінити вплив на погоджених контрольних випадках до введення.","Власники погоджують редакцію, дату та відкриті винятки; змінена чернетка потребує повторного перегляду зачеплених частин.","Уповноважений виконавець вводить погоджену редакцію через перевірений маршрут; збереження схеми або запланована дата не доводять фактичного застосування.","На належну дату прочитати чинну редакцію та перевірити контрольні випадки в потрібних залежних процесах; невідповідність іншої ієрархії не приховувати однаковими назвами.","Зберегти попередню редакцію й підтвердження нового стану; історичні дані, кадрові переведення та розширення прав змінювати лише власними погодженими процесами."],"requirements":["Авторитетна чинна ієрархія з призначенням і стабільними ключами вузлів.","Погоджені зміни, дата застосування й відповідальні власники.","Перелік фактичних залежних політик, маршрутів і звітів та контрольні випадки.","Перевірений маршрут публікації й читання чинної редакції у цільовій системі."],"limitations":["Microsoft описує призначення ієрархій, чернетки та перевірку впливу змін із датами дії; це не готова модель будь-якої організації.","Юридична особа, підрозділ і звітна група мають різні значення; картка не визначає їхній правовий чи обліковий статус.","Публікація ієрархії не підтверджує автоматичного оновлення всіх кадрових записів, прав або зовнішніх систем.","Розробку організаційної стратегії, юридичну реорганізацію, перенесення обліку та міграцію всього ERP не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Підрозділи вже перемістили на схемі, але робочі політики або звіти використовують стару ієрархію чи інше її призначення. Чернетку помилково вважають чинною структурою."],"synonyms":["нова оргструктура не застосувалася до робочих правил","чернетку ієрархії помилково вважають чинною","після переміщення підрозділу звіти використовують стару редакцію структури"],"search_queries":["як ввести нову редакцію внутрішньої організаційної ієрархії з датою дії і перевіркою залежних правил"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/fin-ops-core/fin-ops/organization-administration/tasks/create-organization-hierarchy","title":"Microsoft: створення та публікація організаційної ієрархії","checked_at":"2026-10-15","supports":"Прочитано 31–51: організації, призначення ієрархії, чернетка та публікація. Погодження й приймальні випадки — модель для аудиту."},{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/fin-ops-core/fin-ops/organization-administration/plan-organizational-hierarchy","title":"Microsoft: планування організаційних ієрархій і впливу зміни","checked_at":"2026-10-15","supports":"Прочитано 31–45 і 224–236: область моделі, кілька призначень, дати дії та перевірка впливу. Історію, результати й години потрібно спроєктувати."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"internal-organization-hierarchy-version-release-control-tracked","title":"Контроль із підтвердженням результату","description":"Власник організаційної моделі погоджує зміну внутрішньої ієрархії, дату дії та перевіряє застосування редакції у визначених залежних процесах.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Підрозділ перенесли в чернетці, але одна політика залишилася прив’язаною до іншої ієрархії. Команда виявила це контрольним випадком до введення та погодила належну область зміни.","implementation_methods":["Вести запит, чернетку, оцінку впливу, погодження редакції й перевірку після дати застосування.","Звіряти чинну редакцію та результати залежних процесів через перевірені джерела; невизначений стан публікації передавати відповідальному."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Авторитетна чинна ієрархія з призначенням і стабільними ключами вузлів.","Погоджені зміни, дата застосування й відповідальні власники.","Перелік фактичних залежних політик, маршрутів і звітів та контрольні випадки.","Перевірений маршрут публікації й читання чинної редакції у цільовій системі."],"limitations":["Microsoft описує призначення ієрархій, чернетки та перевірку впливу змін із датами дії; це не готова модель будь-якої організації.","Юридична особа, підрозділ і звітна група мають різні значення; картка не визначає їхній правовий чи обліковий статус.","Публікація ієрархії не підтверджує автоматичного оновлення всіх кадрових записів, прав або зовнішніх систем.","Розробку організаційної стратегії, юридичну реорганізацію, перенесення обліку та міграцію всього ERP не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0548","reason":"Структура клієнтської групи пояснює комерційні зв’язки; вона не вводить версію внутрішньої ієрархії для робочих політик."},{"type":"related","target_id":"AUT-0185","reason":"Кадрове переведення окремої людини не підтверджує публікацію всієї організаційної ієрархії."},{"type":"related","target_id":"AUT-0455","reason":"Дослідження проходження процесу не вводить погоджену організаційну модель у робочі системи."}],"configurator_questions":[{"id":"internal-organization-hierarchy-version-release-control-impact","question":"Чи потрібно перевіряти кілька призначень ієрархії та залежних правил?","help_text":"Надайте фактичні зв’язки політик, маршрутів і звітів із контрольними випадками.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте фактичні зв’язки політик, маршрутів і звітів із контрольними випадками."}]},{"id":"internal-organization-hierarchy-version-release-control-effective","question":"Чи потрібна звірка запланованої редакції після дати введення?","help_text":"Погодьте часову основу, джерело чинної редакції та порядок розбору часткового застосування.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте часову основу, джерело чинної редакції та порядок розбору часткового застосування."}]}]},{"schema_version":1,"id":"AUT-0769","slug":"shipment-packaging-type-and-quantity-plan","title":"Підбір типів і кількості тари для замовлення","summary":"Складська команда отримує перевірений план розподілу товарів між допустимими коробками чи іншою тарою за місткістю, масою та правилами сумісності.","problem":"Пакувальник добирає коробки навмання або розрахунок використовує зовнішній об’єм замість внутрішньої місткості. План не вміщує всі товари чи змішує несумісні рядки.","outcome":"Є погоджений план тари з прив’язкою кожної кількості до замовлення та видимими винятками; його передають на фізичне пакування без заяви про гарантований оптимум.","category":"inventory","subcategory":"stock-control","roles":["warehouse-manager","operations-manager"],"industries":["cross-industry"],"triggers":["Для виділених до відправлення товарних кількостей потрібно визначити допустимі пакувальні одиниці до фізичного пакування."],"workflow_steps":["Зафіксувати редакцію відправлення, товари, виділені кількості й одиниці; перевірити актуальність маси та розмірів товарів.","Отримати допустимі типи тари з внутрішньою місткістю, граничною масою й зовнішніми розмірами; порожню тару та її вагу відокремити від вмісту.","Погодити дозволене змішування замовлень і товарів, орієнтацію та інші фізичні обмеження; невідоме значення не трактувати як відсутність заборони.","Отримати кандидатний розподіл через перевірений засіб розрахунку; зберегти стратегію й параметри без обіцянки мінімальної кількості коробок.","Звірити повноту кожного товарного рядка, відсутність подвійного розподілу та відповідність обмеженням тари; непідібраний залишок передати на рішення.","Керівник складу погоджує план і передає точну редакцію на пакування; фактичні кількості та закриття пакунків підтверджують окремо.","Після зміни складу чи перепакування повторити потрібний розрахунок і погодження; історичний план не видавати за чинний."],"requirements":["Чинне відправлення з виділеними кількостями та перевіреними вимірами товарів.","Допустимі типи тари з внутрішніми обмеженнями та окремими зовнішніми вимірами.","Погоджені правила змішування, орієнтації та приймання плану.","Перевірений розрахунковий засіб і маршрут передавання результату складській команді."],"limitations":["Microsoft описує розподіл виділених кількостей за місткістю, стратегіями й правилами змішування; конкретний WMS і алгоритм потрібно перевіряти.","Сума об’ємів не доводить фізичного розміщення предметів. Доступна орієнтація залежить від способу розрахунку.","План не підтверджує фактичного пакування, закриття коробки, вартості перевезення або передачі перевізнику.","Власний оптимізаційний алгоритм, точні тривимірні моделі, випробування міцності, закупівлю тари й фізичні складські роботи не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Пакувальник добирає коробки навмання або розрахунок використовує зовнішній об’єм замість внутрішньої місткості. План не вміщує всі товари чи змішує несумісні рядки."],"synonyms":["розрахунок пакування використав зовнішній об’єм коробки","товари не вміщуються в запропоновану тару","потрібен план кількості коробок для замовлення"],"search_queries":["як підібрати типи і кількість тари для замовлення за внутрішньою місткістю масою і правилами змішування"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/supply-chain/warehousing/wave-containerization","title":"Microsoft: розподіл товарів між пакувальними одиницями","checked_at":"2026-10-15","supports":"Прочитано 31–115: внутрішня місткість проти зовнішніх вимірів, маса, групи та обмеження змішування. Погодження, звірки й години — модель для аудиту."},{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/dynamics365/supply-chain/warehousing/container-packing-strategy-overview","title":"Microsoft: стратегії розподілу товарів між контейнерами","checked_at":"2026-10-15","supports":"Прочитано 31–115: різні стратегії перевірки відкритих контейнерів. Не доводить глобального оптимуму чи готового конектора."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"shipment-packaging-type-and-quantity-plan-tracked","title":"Контроль із підтвердженням результату","description":"Складська команда отримує перевірений план розподілу товарів між допустимими коробками чи іншою тарою за місткістю, масою та правилами сумісності.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Для замовлення запропонували дві коробки, але одна місткість була задана зовнішніми вимірами. Команда виправила джерело, повторила розрахунок і передала перевірений план; фізичне пакування перевірили окремо.","implementation_methods":["Вести редакцію вхідних кількостей, допустиму тару, правила, кандидатний розподіл і погоджений план.","Зіставляти результат перевіреного розрахункового засобу з потребою замовлення та передавати точну редакцію до складського виконання."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Чинне відправлення з виділеними кількостями та перевіреними вимірами товарів.","Допустимі типи тари з внутрішніми обмеженнями та окремими зовнішніми вимірами.","Погоджені правила змішування, орієнтації та приймання плану.","Перевірений розрахунковий засіб і маршрут передавання результату складській команді."],"limitations":["Microsoft описує розподіл виділених кількостей за місткістю, стратегіями й правилами змішування; конкретний WMS і алгоритм потрібно перевіряти.","Сума об’ємів не доводить фізичного розміщення предметів. Доступна орієнтація залежить від способу розрахунку.","План не підтверджує фактичного пакування, закриття коробки, вартості перевезення або передачі перевізнику.","Власний оптимізаційний алгоритм, точні тривимірні моделі, випробування міцності, закупівлю тари й фізичні складські роботи не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0110","reason":"Звірка фактичного складу пакунків не визначає кандидатну тару до фізичного пакування."},{"type":"related","target_id":"AUT-0216","reason":"Спільне відправлення не визначає розподіл товарів між його коробками."},{"type":"related","target_id":"AUT-0376","reason":"Транспортну етикетку оформлюють для конкретного пакунка; вона не розраховує, як розподілити товарну кількість."},{"type":"related","target_id":"AUT-0228","reason":"Залишок багаторазової тари у клієнтів не підбирає план пакування нового замовлення."},{"type":"related","target_id":"AUT-0743","reason":"Розкрій листів змінює матеріал на деталі; пакувальний план розподіляє готові товари без виробничого різання."}],"configurator_questions":[{"id":"shipment-packaging-type-and-quantity-plan-constraints","question":"Чи потрібна звірка кількох типів тари та правил змішування?","help_text":"Надайте виміри, одиниці, масу, допустиму орієнтацію й правила сумісності рядків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте виміри, одиниці, масу, допустиму орієнтацію й правила сумісності рядків."}]},{"id":"shipment-packaging-type-and-quantity-plan-revisions","question":"Чи потрібне передавання плану та повторний розрахунок після змін?","help_text":"Погодьте джерело редакції замовлення, маршрут виконання й підтвердження застосованого плану.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте джерело редакції замовлення, маршрут виконання й підтвердження застосованого плану."}]}]},{"schema_version":1,"id":"AUT-0770","slug":"business-application-retirement-dependency-handover","title":"Контроль виведення бізнес-застосунку з експлуатації","summary":"Власник сервісу погоджує завершення роботи застосунку та звіряє залежності, збереження потрібних даних і остаточний стан пов’язаних ресурсів.","problem":"Застосунок вимкнули, але інтеграції ще звертаються до нього, завдання запускають його знову або потрібні дані лишилися без власника. Запис про закриття не відповідає фактичному стану сервісу.","outcome":"Є погоджений результат виведення, підтверджені доля даних і перехід споживачів та видимі залишкові зобов’язання; вимкнений сервер не вважають завершенням усієї роботи.","category":"project-operations","subcategory":"task-management","roles":["operations-manager","project-manager","owner"],"industries":["cross-industry"],"triggers":["Власник бізнес-сервісу погодив підготовку до остаточного завершення використання конкретного застосунку."],"workflow_steps":["Зафіксувати точну область застосунку, середовища, власників і підставу виведення; спільні ресурси інших сервісів позначити окремо.","Зібрати підтверджені вхідні й вихідні залежності, користувачів, планові запуски та потрібні дані; відсутність відомого власника не вважати відсутністю використання.","Погодити перехід кожного споживача, збереження або перенесення даних і перевірку доступності збереженого; заборони видалення та незавершені зобов’язання лишити явними.","Власники погоджують послідовність, контрольні точки й критерії зупинки; незворотні дії не виконують лише за календарною датою.","Виконавці застосовують дозволений план через власні інструменти; для кожної залежності, розкладу й ресурсу зберігають фактичний результат, не вимикаючи спільне без підтвердження.","У погодженому вікні перевірити залишкові звернення та повторні запуски, доступ до збережених даних і роботу споживачів; новий трафік передати на розбір.","Звірити реєстр сервісів, стан ліцензій та відкритих витрат із підтвердженнями власників; неврегульований залишок не приховувати статусом «виведено»."],"requirements":["Погоджена область застосунку та відповідальні власники сервісу й даних.","Перевірений перелік споживачів, розкладів, середовищ і спільних ресурсів.","План переходу, збереження потрібних даних, приймання та дозволених незворотних дій.","Авторитетні докази виконання й контрольне вікно спостереження."],"limitations":["AWS описує залежності, контрольоване завершення та збереження потрібних налаштувань і даних; конкретні кроки залежать від середовища.","Завершення ліцензії чи вимкнення сервера не доводить переходу всіх споживачів або припинення всіх витрат.","Захист, моніторинг і резервування не відключають автоматично до підтвердження погоджених передумов; політики зберігання залишаються чинними.","Технічну міграцію, фізичне знищення носіїв, видалення даних, зміну зовнішніх систем і гарантовану економію не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Застосунок вимкнули, але інтеграції ще звертаються до нього, завдання запускають його знову або потрібні дані лишилися без власника. Запис про закриття не відповідає фактичному стану сервісу."],"synonyms":["застосунок вимкнули але залежні сервіси продовжують звернення","закритий сервіс знову запускається за розкладом","після виведення застосунку не підтверджено доступність потрібних даних"],"search_queries":["як контролювати виведення бізнес застосунку з експлуатації залежності збереження даних і залишкові запуски"],"sources":[{"type":"vendor_documentation","url":"https://docs.aws.amazon.com/prescriptive-guidance/latest/migration-app-retirement-best-practices/best-practices.html","title":"AWS: підготовка й контроль виведення застосунків","checked_at":"2026-10-15","supports":"Прочитано 5–150: залежності, план, контрольоване завершення, дані та реєстри. Конкретні дозволи, контрольні точки й години — модель для аудиту; деструктивні рекомендації не є дозволом виконання."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"business-application-retirement-dependency-handover-tracked","title":"Контроль із підтвердженням результату","description":"Власник сервісу погоджує завершення роботи застосунку та звіряє залежності, збереження потрібних даних і остаточний стан пов’язаних ресурсів.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Після погодженого вимкнення застосунку знайшли регулярні звернення звітного сервісу. Виведення залишили відкритим, перенесли споживача та повторно перевірили дані; спільне сховище не видаляли.","implementation_methods":["Вести план виведення з власниками залежностей, передумовами, доказами виконання й невирішеним залишком.","Звіряти дозволені результати зовнішніх виконавців та реєстри; система координації не виконує незворотних технічних дій за загальним статусом."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Погоджена область застосунку та відповідальні власники сервісу й даних.","Перевірений перелік споживачів, розкладів, середовищ і спільних ресурсів.","План переходу, збереження потрібних даних, приймання та дозволених незворотних дій.","Авторитетні докази виконання й контрольне вікно спостереження."],"limitations":["AWS описує залежності, контрольоване завершення та збереження потрібних налаштувань і даних; конкретні кроки залежать від середовища.","Завершення ліцензії чи вимкнення сервера не доводить переходу всіх споживачів або припинення всіх витрат.","Захист, моніторинг і резервування не відключають автоматично до підтвердження погоджених передумов; політики зберігання залишаються чинними.","Технічну міграцію, фізичне знищення носіїв, видалення даних, зміну зовнішніх систем і гарантовану економію не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0145","reason":"Окрема ІТ-зміна підтримує технічне виконання, але не закриває життєвий цикл застосунку, його споживачів і даних."},{"type":"related","target_id":"AUT-0419","reason":"Передавання сервісу в підтримку не підтверджує завершення його використання."},{"type":"related","target_id":"AUT-0197","reason":"Рішення щодо строку зберігання даних не виводить застосунок і не переносить його споживачів."},{"type":"related","target_id":"AUT-0428","reason":"Перегляд ліцензій не підтверджує вимкнення сервісу й завершення його залежностей."},{"type":"related","target_id":"AUT-0088","reason":"Тест відновлення копії не доводить переходу всіх споживачів або припинення використання застосунку."}],"configurator_questions":[{"id":"business-application-retirement-dependency-handover-dependencies","question":"Чи потрібно звіряти кілька споживачів і спільних ресурсів?","help_text":"Надайте карту залежностей, власників і критерії фактичного переходу споживачів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте карту залежностей, власників і критерії фактичного переходу споживачів."}]},{"id":"business-application-retirement-dependency-handover-data","question":"Чи потрібні контроль збережених даних і перевірка залишкових запусків?","help_text":"Погодьте область збереження, докази доступності, строки спостереження та маршрут невирішених звернень.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Погодьте область збереження, докази доступності, строки спостереження та маршрут невирішених звернень."}]}]},{"schema_version":1,"id":"AUT-0771","slug":"media-content-id-reference-registration-review","title":"Погодження та звірка еталонного матеріалу для Content ID","summary":"Команда перевіряє допустимість медіаматеріалу як еталона — джерела автоматичного зіставлення — та підтверджує фактичні налаштування Content ID.","problem":"Дозвіл опублікувати відео помилково сприймають як право заявляти збіги чужих завантажень. До еталона потрапляють невиключні фрагменти або обирають непогоджену політику дій.","outcome":"Є погоджений придатний еталон, точна область прав і перевірені налаштування; сумнівні фрагменти не запускають автоматичне заявлення прав без рішення.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Власник прав пропонує медіаматеріал для створення або зміни еталона автоматичного зіставлення в Content ID."],"workflow_steps":["Ідентифікувати твір, точну редакцію файла, власника прав і доступний партнерський інструмент; публічне відео відокремити від еталона та об’єкта прав.","Уповноважений фахівець перевіряє виключні права й території та склад сторонніх фрагментів; дозвіл на публікацію не прирівнювати до придатності еталона.","Звірити матеріал із чинними правилами сервісу та потрібними метаданими; непридатний або неоднозначний склад повернути на рішення до увімкнення зіставлення.","Погодити точну політику для знайдених збігів та необхідний ручний перегляд; наявний шаблон не вважати погодженням команди.","Уповноважений виконавець створює або змінює еталон дозволеним способом; зберегти ідентифікатори, редакцію й результат без повторного подання за невизначеної відповіді.","Прочитати фактичний стан еталона, пов’язаний об’єкт прав і політику; доступність публічного ролика не доводить належного зіставлення.","За зміни прав, помилкового еталона чи повідомлення сервісу передати випадок відповідальному для належної зміни й перевірки результату; окремі претензії не закривати лише зміною еталона."],"requirements":["Перевірені права, території та дозволений доступ до партнерського Content ID.","Точна редакція матеріалу й опис сторонніх складових.","Погоджені метадані, політика збігів та правила ручного перегляду.","Джерело фактичного стану еталона й уповноважений власник рішення."],"limitations":["YouTube надає ці можливості визначеним партнерам; звичайне завантаження ролика не підтверджує доступу до керування еталонами.","Придатність еталона має окремі вимоги; не кожний матеріал із дозволом використання підходить для автоматичного заявлення збігів.","Збіг не є самостійним юридичним висновком. Автоматизація не обирає підстави прав або політику без уповноваженого рішення.","Отримання партнерського статусу, правова експертиза, власний алгоритм розпізнавання й реальні подання претензій не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Дозвіл опублікувати відео помилково сприймають як право заявляти збіги чужих завантажень. До еталона потрапляють невиключні фрагменти або обирають непогоджену політику дій."],"synonyms":["дозвіл на відео не підтверджує право створити еталон Content ID","еталон містить невиключні сторонні фрагменти","політика збігів Content ID не відповідає погодженій"],"search_queries":["як перевірити і зареєструвати еталонний матеріал Content ID права території метадані і політику збігів"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/youtube/answer/2605065?hl=en","title":"YouTube: допустимий матеріал для Content ID","checked_at":"2026-10-15","supports":"Прочитано 17–83: партнерське охоплення, допустимість еталона, права, індивідуальні матеріали й метадані. Погодження та години — модель для аудиту."},{"type":"vendor_documentation","url":"https://support.google.com/youtube/answer/107007?hl=en-GB","title":"YouTube: створення еталона для зіставлення","checked_at":"2026-10-15","supports":"Прочитано 17–47: окреме ввімкнення зіставлення та політика. Конкретний акаунт і API-адаптер не перевірено."},{"type":"vendor_documentation","url":"https://support.google.com/youtube/answer/107004?hl=en","title":"YouTube: відмінність еталона, відео та об’єкта прав","checked_at":"2026-10-15","supports":"Прочитано 17–55: різні об’єкти та значення стану еталона. Звірка після зміни — власна модель."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"media-content-id-reference-registration-review-tracked","title":"Контроль із підтвердженням результату","description":"Команда перевіряє допустимість медіаматеріалу як еталона — джерела автоматичного зіставлення — та підтверджує фактичні налаштування Content ID.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"У погодженому до публікації ролику знайшли невиключну фонову музику. Команда не ввімкнула для всього файла автоматичне зіставлення, а передала придатність і склад еталона власнику прав на окреме рішення.","implementation_methods":["Вести перевірку придатності, погоджений склад еталона, метадані, політику та докази фактичного стану.","Зіставляти результати уповноваженого партнера з погодженою редакцією; сам дозвіл на публікацію не відкриває маршрут автоматичних претензій."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Перевірені права, території та дозволений доступ до партнерського Content ID.","Точна редакція матеріалу й опис сторонніх складових.","Погоджені метадані, політика збігів та правила ручного перегляду.","Джерело фактичного стану еталона й уповноважений власник рішення."],"limitations":["YouTube надає ці можливості визначеним партнерам; звичайне завантаження ролика не підтверджує доступу до керування еталонами.","Придатність еталона має окремі вимоги; не кожний матеріал із дозволом використання підходить для автоматичного заявлення збігів.","Збіг не є самостійним юридичним висновком. Автоматизація не обирає підстави прав або політику без уповноваженого рішення.","Отримання партнерського статусу, правова експертиза, власний алгоритм розпізнавання й реальні подання претензій не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0255","reason":"Дозвіл використання маркетингового матеріалу не підтверджує придатності еталона для автоматичного заявлення збігів."},{"type":"related","target_id":"AUT-0703","reason":"Отримана претензія стосується конкретного відео й заявника; реєстрація власного еталона має інший об’єкт."},{"type":"related","target_id":"AUT-0693","reason":"Звернення щодо вже знайденої сторонньої копії не створює еталона й не перевіряє політику автоматичних збігів."}],"configurator_questions":[{"id":"media-content-id-reference-registration-review-rights","question":"Чи потрібно звіряти кілька територій і складових матеріалу?","help_text":"Надайте погоджені права, території, сторонні фрагменти й правила їх допустимості.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте погоджені права, території, сторонні фрагменти й правила їх допустимості."}]},{"id":"media-content-id-reference-registration-review-state","question":"Чи потрібна перевірка політики й стану після створення або зміни?","help_text":"Погодьте ідентифікатори еталона та об’єкта прав, джерело стану й маршрут винятків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте ідентифікатори еталона та об’єкта прав, джерело стану й маршрут винятків."}]}]},{"schema_version":1,"id":"AUT-0772","slug":"published-editorial-factual-error-correction-control","title":"Контроль редакційного виправлення фактичної помилки","summary":"Редакція перевіряє повідомлення про фактичну помилку, погоджує виправлення та підтверджує зрозуміле повідомлення аудиторії й одержувачам матеріалу.","problem":"Фактичну помилку тихо змінюють у тексті або виправляють лише одну копію. Читачі й партнери продовжують використовувати хибну редакцію, а підтверджене виправлення не відрізняють від звичайного оновлення.","outcome":"Є редакційне рішення за перевіреними фактами, позначене виправлення та видимі результати для відомих похідних публікацій; непідтверджену скаргу не називають визнаною помилкою.","category":"documents","subcategory":"records","roles":["marketer","operations-manager"],"industries":["cross-industry"],"triggers":["Редакція отримала повідомлення про можливу фактичну помилку в уже опублікованому матеріалі."],"workflow_steps":["Зберегти точну первинну редакцію, адреси або ідентифікатори матеріалу, повідомлену помилку й докази; повторне повідомлення пов’язати з чинною справою.","Передати автору та відповідальному редактору факти для перевірки; нові відомості відокремити від помилки, яка існувала на момент публікації.","Редактор погоджує обґрунтоване рішення й точний текст виправлення або відхилення; автоматичний пошук чи ШІ не визначає достовірності замість редакції.","За підтвердженої помилки визначити відомі публікації й одержувачів, які використали матеріал, та потрібне зрозуміле маркування виправлення для кожного формату.","Уповноважений виконавець публікує погоджене виправлення та передає його потрібним партнерам; факт відправлення не доводить зміни партнерської копії.","Прочитати фактично видимий матеріал і повідомлення про виправлення; нерозглянуті чи незмінені відомі копії залишити окремими наступними діями.","Зберегти первинну й виправлену редакції, автора рішення та докази; новий істотний факт повертає справу на редакційний перегляд."],"requirements":["Точна помилкова редакція та дозволені докази для перевірки фактів.","Уповноважений редактор і погоджена політика виправлень.","Відомі похідні публікації й одержувачі з визначеним способом повідомлення.","Доступні фактичні результати публікації та журнал редакцій."],"limitations":["AP описує власну політику прозорого виправлення й повідомлення одержувачів; це приклад редакційної практики, а не універсальний закон.","Не є зміною матеріалу лише тому, що першоджерело пізніше оновилося; редактор визначає, чи справді була фактична помилка.","Неможливо гарантувати знаходження й зміну всіх сторонніх копій. Невідома область поширення залишається обмеженням.","Юридичні спори, автоматичне визначення істини, примусове вилучення матеріалів і керування помилковою маркетинговою доставкою не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Фактичну помилку тихо змінюють у тексті або виправляють лише одну копію. Читачі й партнери продовжують використовувати хибну редакцію, а підтверджене виправлення не відрізняють від звичайного оновлення."],"synonyms":["фактичну помилку тихо змінили без позначки виправлення","партнери продовжують цитувати помилкову редакцію матеріалу","редакційне виправлення не дійшло до відомих одержувачів"],"search_queries":["як контролювати редакційне виправлення фактичної помилки позначення і повідомлення одержувачів матеріалу"],"sources":[{"type":"vendor_documentation","url":"https://www.ap.org/about/news-values-and-principles/telling-the-story/","title":"AP: редакційні виправлення та повідомлення одержувачів","checked_at":"2026-10-15","supports":"Прочитано 262–291 розділу Integrity / Corrections: редактор, прозоре маркування й передавання виправлення. Облік копій, рішення та години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"published-editorial-factual-error-correction-control-tracked","title":"Контроль із підтвердженням результату","description":"Редакція перевіряє повідомлення про фактичну помилку, погоджує виправлення та підтверджує зрозуміле повідомлення аудиторії й одержувачам матеріалу.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"У публікації неправильно зазначили кількість філій за чинним на той день документом. Редактор підтвердив помилку, погодив позначене виправлення й повідомлення партнеру, який використав матеріал. Партнерську копію лишили відкритою дією до підтвердження.","implementation_methods":["Вести повідомлення, перевірку фактів, редакційне рішення, редакції та докази видимого виправлення.","Пов’язувати відомі похідні матеріали й підтвердження одержувачів із точною справою; невідомі копії не вважати автоматично виправленими."],"complexity":"medium","hours_min":24,"hours_max":48,"requirements":["Точна помилкова редакція та дозволені докази для перевірки фактів.","Уповноважений редактор і погоджена політика виправлень.","Відомі похідні публікації й одержувачі з визначеним способом повідомлення.","Доступні фактичні результати публікації та журнал редакцій."],"limitations":["AP описує власну політику прозорого виправлення й повідомлення одержувачів; це приклад редакційної практики, а не універсальний закон.","Не є зміною матеріалу лише тому, що першоджерело пізніше оновилося; редактор визначає, чи справді була фактична помилка.","Неможливо гарантувати знаходження й зміну всіх сторонніх копій. Невідома область поширення залишається обмеженням.","Юридичні спори, автоматичне визначення істини, примусове вилучення матеріалів і керування помилковою маркетинговою доставкою не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0418","reason":"Оновлення першоджерела не означає фактичної помилки на момент публікації; тут потрібне окреме редакційне рішення й видиме виправлення."},{"type":"related","target_id":"AUT-0614","reason":"Інцидент маркетингової розсилки контролює доставку та виправну кампанію; він не встановлює редакційної процедури визнаної фактичної помилки в матеріалі."},{"type":"related","target_id":"AUT-0103","reason":"Планова публікація не підтверджує позначеного виправлення та повідомлення тих, хто вже використав хибний матеріал."},{"type":"related","target_id":"AUT-0622","reason":"Доказ рекламної обіцянки перед використанням не закриває випадку редакційної помилки й виправлення похідних публікацій."}],"configurator_questions":[{"id":"published-editorial-factual-error-correction-control-copies","question":"Чи потрібно звіряти кілька відомих похідних публікацій?","help_text":"Надайте зв’язки матеріалів, формати й відповідальних за фактичне виправлення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте зв’язки матеріалів, формати й відповідальних за фактичне виправлення."}]},{"id":"published-editorial-factual-error-correction-control-partners","question":"Чи потрібен контроль повідомлення партнерів і результату їхніх копій?","help_text":"Погодьте одержувачів, дозволений текст повідомлення та межі підтвердження сторонніх змін.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте одержувачів, дозволений текст повідомлення та межі підтвердження сторонніх змін."}]}]},{"schema_version":1,"id":"AUT-0773","slug":"engineering-model-clash-resolution-verification","title":"Звірка усунення колізій між інженерними моделями","summary":"Координатор пов’язує кожну виявлену колізію з редакціями моделей, передає її відповідальним і перевіряє результат повторного тесту після зміни.","problem":"Інженерне зауваження позначили вирішеним, але перевірку виконали для старої моделі або змінили область тесту. Колізія лишилася чи зникла зі звіту через інше охоплення.","outcome":"Є перевірений результат для точних редакцій і правил тесту, а погоджений виняток відокремлений від фактичного зникнення перетину.","category":"project-operations","subcategory":"task-management","roles":["project-manager","operations-manager"],"industries":["cross-industry"],"triggers":["Перевірка суміщених інженерних моделей виявила колізію або надійшла нова редакція моделі для перевірки її усунення."],"workflow_steps":["Зафіксувати редакції моделей, область елементів, координатну основу, параметри й ідентифікатор тесту; невідоме суміщення передати координатору.","Пов’язати результат із конкретними елементами, місцем і доказом; повторний запис того самого випадку зіставити з чинною справою.","Компетентний координатор визначає відповідального та потрібне рішення: виправлення, додаткові дані або обґрунтований виняток; статус не підміняє інженерного висновку.","Після виправлення звірити нові редакції та чинність правил тесту; зміну допуску чи виключення елементів погодити окремо від зміни конструкції.","Отримати результат повторної перевірки для потрібного охоплення; порівняти фактичну наявність колізії, нові випадки й погоджені винятки.","Приймальник підтверджує конкретний результат із доказом; ручне закриття задачі або статус перевірки не доводять безпеки всього проєкту.","При новій редакції чи повторній появі відкрити належний перегляд зі збереженням історії; старий тест не вважати актуальним для нової моделі."],"requirements":["Доступні редакції інженерних моделей з дозволеним використанням.","Погоджена координатна основа, склад і параметри тесту.","Ідентифікатори колізій або правила зіставлення результатів між перевірками.","Компетентні відповідальні й приймальник виправлення або винятку."],"limitations":["Autodesk описує призначення й стани колізій; поточний засіб, версію та відповідність станів потрібно перевіряти окремо.","Історична документація Navisworks 2020 відрізняє погоджений випадок від відсутності колізії після тесту; це не гарантія незмінної семантики всіх інтеграцій.","Зміна охоплення, допуску чи редакції обмежує пряме порівняння. Відсутність рядка у відфільтрованому звіті не доводить виправлення.","Розробку моделей і власного геометричного рушія, інженерні розрахунки, будівельні роботи та ліцензії не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Інженерне зауваження позначили вирішеним, але перевірку виконали для старої моделі або змінили область тесту. Колізія лишилася чи зникла зі звіту через інше охоплення."],"synonyms":["колізію закрили без повторного тесту нової моделі","перетин зник зі звіту через зміну області перевірки","статус погоджено помилково прийняли за усунення колізії"],"search_queries":["як звіряти усунення колізій між інженерними моделями повторний тест редакції і погоджені винятки"],"sources":[{"type":"vendor_documentation","url":"https://help.autodesk.com/cloudhelp/2026/ENU/Navisworks-Clash-Detective/files/GUID-B354BA25-836F-4244-AD5F-1B779B32A4D9.htm","title":"Autodesk: призначення та опрацювання колізій","checked_at":"2026-10-15","supports":"Прочитано 0–36: статуси, групи й призначення. Правила приймання, зіставлення та години — модель для аудиту."},{"type":"vendor_documentation","url":"https://help.autodesk.com/cloudhelp/2020/ENU/Navisworks/files/GUID-FCC9E5E1-2717-48D2-8DBE-2055CF2DC61E.htm","title":"Autodesk: результати й повторний тест колізій, редакція 2020","checked_at":"2026-10-15","supports":"Прочитано 0–120: актуальність результатів після зміни й розрізнення погодження та усунення. Конкретну актуальну інтеграцію не перевірено."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"engineering-model-clash-resolution-verification-tracked","title":"Контроль із підтвердженням результату","description":"Координатор пов’язує кожну виявлену колізію з редакціями моделей, передає її відповідальним і перевіряє результат повторного тесту після зміни.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Підрядник закрив колізію, але звіт містив стару редакцію вентиляції. Координатор повернув випадок на повторну перевірку з погодженим складом; ручний статус не зарахували як доказ виправлення.","implementation_methods":["Вести зв’язки редакцій, тестів, елементів, призначень і підтверджень повторної перевірки.","Зіставляти результати перевіреного засобу з погодженим охопленням; інженерне рішення залишати компетентному приймальнику."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Доступні редакції інженерних моделей з дозволеним використанням.","Погоджена координатна основа, склад і параметри тесту.","Ідентифікатори колізій або правила зіставлення результатів між перевірками.","Компетентні відповідальні й приймальник виправлення або винятку."],"limitations":["Autodesk описує призначення й стани колізій; поточний засіб, версію та відповідність станів потрібно перевіряти окремо.","Історична документація Navisworks 2020 відрізняє погоджений випадок від відсутності колізії після тесту; це не гарантія незмінної семантики всіх інтеграцій.","Зміна охоплення, допуску чи редакції обмежує пряме порівняння. Відсутність рядка у відфільтрованому звіті не доводить виправлення.","Розробку моделей і власного геометричного рушія, інженерні розрахунки, будівельні роботи та ліцензії не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0440","reason":"Технічна відповідь на запит не підтверджує відсутності колізії в потрібних редакціях моделей."},{"type":"related","target_id":"AUT-0442","reason":"Приймання фізичного будівельного зауваження не повторює міжмодельний тест."},{"type":"related","target_id":"AUT-0755","reason":"Виправлення однієї сіткової моделі перед друком не перевіряє перетини між інженерними моделями."},{"type":"related","target_id":"AUT-0754","reason":"Приймальні бізнес-сценарії ІТ-системи не визначають область і геометричний результат інженерного тесту."}],"configurator_questions":[{"id":"engineering-model-clash-resolution-verification-models","question":"Чи потрібна звірка кількох моделей, редакцій і правил тестування?","help_text":"Надайте ключі елементів, координатну основу, параметри та правила зіставлення результатів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте ключі елементів, координатну основу, параметри та правила зіставлення результатів."}]},{"id":"engineering-model-clash-resolution-verification-retests","question":"Чи потрібен контроль повторних перевірок і погоджених винятків?","help_text":"Погодьте критерії приймання, відповідальних, докази й маршрут повторної появи колізії.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте критерії приймання, відповідальних, докази й маршрут повторної появи колізії."}]}]},{"schema_version":1,"id":"AUT-0774","slug":"analytical-method-fitness-for-purpose-acceptance","title":"Погодження придатності аналітичної методики до застосування","summary":"Лабораторія погоджує план перевірки методики, зіставляє докази з наперед визначеними критеріями та фіксує межі підтвердженого використання.","problem":"Методику починають використовувати лише за наявності документа чи окремого успішного вимірювання. Не визначено потрібне охоплення й критерії, а після дослідження підлаштовують вимоги під отримані результати.","outcome":"Є погоджений план, простежувані результати й висновок уповноваженого фахівця щодо придатності точної редакції методики у визначених межах.","category":"production","subcategory":"quality-control","roles":["operations-manager","owner"],"industries":["cross-industry"],"triggers":["Запропоновано нову або змінену аналітичну методику, для якої потрібно підтвердити придатність до погодженого застосування."],"workflow_steps":["Зафіксувати завершену редакцію методики, призначення, типи матеріалів і потрібне охоплення; розроблення методики відокремити від її перевірки.","Фахівець визначає характеристики, критерії приймання й достатність дослідження за застосовними вимогами та ризиком; критерії погодити до аналізу результатів.","Звірити план вимірювань, матеріали, обладнання, повторення й спосіб аналізу; наявні докази використати лише в межах підтвердженої застосовності.","Пов’язати фактичні вимірювання й відхилення з погодженим планом; пропущені частини не вважати успішними, а зміну плану зберегти окремою редакцією.","Отримати перевірені підсумки кожної характеристики та невизначеності висновку; один вдалий показник не замінює потрібного охоплення.","Уповноважений фахівець погоджує звіт і межі придатності, доопрацювання або відмову; висновок не поширювати на невивчені матеріали й умови.","Передати саме прийняту редакцію до робочих процедур та контролю якості; істотна зміна умов повертає застосовність на належний перегляд."],"requirements":["Описана редакція методики й погоджена мета використання.","Компетентний фахівець і застосовні правила валідації або перевірки.","Погоджений план, матеріали, вимірювання й перевірений спосіб аналізу.","Джерела первинних результатів та дозволений маршрут приймання методики."],"limitations":["Eurachem надає настанови й приклад планування, а не універсальний обов’язковий шаблон для всіх лабораторій.","Потрібні характеристики й обсяг визначає фахівець; картка не встановлює експериментів або числових критеріїв за замовчуванням.","Калібрування приладу або участь у зовнішньому раунді не доводять придатності методики в усьому потрібному охопленні.","Розроблення методики, лабораторні експерименти, матеріали, акредитацію та власний статистичний рушій не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Методику починають використовувати лише за наявності документа чи окремого успішного вимірювання. Не визначено потрібне охоплення й критерії, а після дослідження підлаштовують вимоги під отримані результати."],"synonyms":["методику ввели без погодженого плану перевірки придатності","критерії методики змінили після отримання результатів","висновок про метод поширили на неперевірені матеріали"],"search_queries":["як погоджувати придатність аналітичної методики план критерії результати і межі застосування"],"sources":[{"type":"vendor_documentation","url":"https://eurachem.org/images/stories/Guides/pdf/MV_Guide_planning_supplement_2nd_ed_EN.pdf","title":"Eurachem: планування та звіт про перевірку методики, 2025","checked_at":"2026-10-15","supports":"Прочитано 101–225, друковані сторінки 3–6: призначення, план, охоплення, результати й погодження. Власні зв’язки, маршрути та години — модель для аудиту."},{"type":"vendor_documentation","url":"https://eurachem.org/index.php/publications/guides/mv","title":"Eurachem: придатність аналітичних методик, третя редакція 2025","checked_at":"2026-10-15","supports":"Прочитано 41–90: область основної настанови та зв’язок із додатком. Повний основний посібник не прочитано."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"analytical-method-fitness-for-purpose-acceptance-tracked","title":"Контроль із підтвердженням результату","description":"Лабораторія погоджує план перевірки методики, зіставляє докази з наперед визначеними критеріями та фіксує межі підтвердженого використання.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Лабораторія отримала добрі результати для одного матеріалу, але план охоплював ще два. Приймальник залишив потрібні частини відкритими й не дозволив назвати методику підтвердженою для всього заявленого охоплення.","implementation_methods":["Вести погоджені редакції плану, джерела доказів, пропуски, висновок і межі прийнятого застосування.","Зіставляти перевірені результати з наперед погодженими критеріями; технічне рішення залишати компетентному власнику методики."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Описана редакція методики й погоджена мета використання.","Компетентний фахівець і застосовні правила валідації або перевірки.","Погоджений план, матеріали, вимірювання й перевірений спосіб аналізу.","Джерела первинних результатів та дозволений маршрут приймання методики."],"limitations":["Eurachem надає настанови й приклад планування, а не універсальний обов’язковий шаблон для всіх лабораторій.","Потрібні характеристики й обсяг визначає фахівець; картка не встановлює експериментів або числових критеріїв за замовчуванням.","Калібрування приладу або участь у зовнішньому раунді не доводять придатності методики в усьому потрібному охопленні.","Розроблення методики, лабораторні експерименти, матеріали, акредитацію та власний статистичний рушій не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0120","reason":"Протокол окремого вимірювання не підтверджує придатності всієї аналітичної методики."},{"type":"related","target_id":"AUT-0123","reason":"Калібрування стосується конкретного приладу та його результатів, а не повного дослідження придатності методики."},{"type":"related","target_id":"AUT-0725","reason":"Зовнішній раунд дає власну оцінку; її застосовність до приймання методики перевіряють окремо."},{"type":"related","target_id":"AUT-0722","reason":"Здатність виробничого процесу виконувати допуски не є валідацією аналітичної методики."}],"configurator_questions":[{"id":"analytical-method-fitness-for-purpose-acceptance-coverage","question":"Чи потрібно звіряти кілька характеристик і областей застосування?","help_text":"Надайте погоджений план, межі, критерії та правила прийнятності наявних доказів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте погоджений план, межі, критерії та правила прийнятності наявних доказів."}]},{"id":"analytical-method-fitness-for-purpose-acceptance-report","question":"Чи потрібен контроль редакцій плану, звіту та передавання в роботу?","help_text":"Погодьте джерела вимірювань, зміни плану, приймальника й докази введення потрібної редакції.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Погодьте джерела вимірювань, зміни плану, приймальника й докази введення потрібної редакції."}]}]},{"schema_version":1,"id":"AUT-0775","slug":"document-generation-template-revision-acceptance","title":"Введення перевіреної редакції шаблону автоматичного документа","summary":"Команда погоджує змінений шаблон, перевіряє підстановку даних і вигляд результатів та звіряє, що нова генерація використовує потрібну редакцію.","problem":"Юрист погодив текст шаблону, але змінні або форматування зламалися при генерації. Ручна й автоматична підготовка створюють документи з різних редакцій.","outcome":"Є перевірений шаблон, погоджені результати контрольної генерації й підтверджена область введення; раніше створені документи зберігають свою історію.","category":"documents","subcategory":"generation","roles":["operations-manager","owner"],"industries":["cross-industry"],"triggers":["Підготовлено нову редакцію шаблону, який використовують для автоматичного формування документів."],"workflow_steps":["Зафіксувати чинний шаблон, причину зміни, кандидатну редакцію та місця використання; погодження юридичного тексту відокремити від перевірки генерації.","Звірити підстановки з доступними даними, назвами й форматами полів; зміни джерел або відсутні значення передати власнику правил.","Підготувати дозволені контрольні дані для потрібних випадків, включно з порожніми реквізитами й повторюваними рядками, якщо вони є в шаблоні.","Отримати контрольні документи для погоджених вихідних форматів; перевірити фактичні значення, читабельність, розриви й істотний зміст, а не лише успішне створення файла.","Власники погоджують точну редакцію та докази; невідповідність форматування або даних повернути на виправлення й повторну генерацію.","Уповноважений виконавець вводить шаблон дозволеним способом; прочитати результат нової ручної або автоматичної генерації в потрібній області.","Зберегти зв’язок документа з використаною редакцією та дату введення; раніше видані або підписані документи не замінювати мовчки."],"requirements":["Погоджені текст, джерела даних і правила підстановки.","Точні чинна й кандидатна редакції шаблону та перелік їх використань.","Дозволені контрольні дані й критерії змісту та вигляду результату.","Перевірені формати й можливості шаблонів у цільовому акаунті."],"limitations":["PlanFix документує шаблони Word і Excel та підстановку даних; керування редакціями й маршрут введення тут є проєктною моделлю.","Компоненти формування можуть змінювати форматування, особливо PDF. Вигляд вихідного шаблону не доводить вигляду створеного документа.","Юридично погоджений текст не підтверджує правильності змінних; контрольна генерація не замінює потрібного юридичного рішення.","Юридичну експертизу, масове переоформлення старих документів, власний редактор і готовий API-адаптер не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Юрист погодив текст шаблону, але змінні або форматування зламалися при генерації. Ручна й автоматична підготовка створюють документи з різних редакцій."],"synonyms":["після заміни шаблону документи містять неправильні змінні","погоджений шаблон неправильно виглядає у створеному PDF","автоматична генерація використала стару редакцію шаблону"],"search_queries":["як ввести нову редакцію шаблону автоматичного документа перевірити змінні форматування і фактичну генерацію"],"sources":[{"type":"vendor_documentation","url":"https://planfix.com/ru/help/Шаблоны_документов","title":"PlanFix: шаблони та формування документів","checked_at":"2026-10-15","supports":"Прочитано 130–200: підстановки, завантаження, ручне й сценарне формування та формат результату. Редакції, погодження й години — модель для аудиту."},{"type":"vendor_documentation","url":"https://planfix.com/ru/help/Ограничения_при_использовании_шаблонов_документов","title":"PlanFix: обмеження форматування створених документів","checked_at":"2026-10-15","supports":"Прочитано 0–17: можливі відмінності вигляду результату від шаблону. Конкретні змінні, акаунт та адаптер не перевірено."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"document-generation-template-revision-acceptance-tracked","title":"Контроль із підтвердженням результату","description":"Команда погоджує змінений шаблон, перевіряє підстановку даних і вигляд результатів та звіряє, що нова генерація використовує потрібну редакцію.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Новий текст договору погодили, але контрольний PDF переніс блок підпису на іншу сторінку й не підставив порожній реквізит за потрібним правилом. Шаблон повернули на доопрацювання до введення в автоматичну генерацію.","implementation_methods":["Вести редакції шаблону, контрольні приклади, погодження результатів і докази використання після введення.","Звіряти документи, сформовані перевіреним маршрутом PlanFix, із погодженою редакцією; поведінку конкретного акаунта перевірити на аудиті."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Погоджені текст, джерела даних і правила підстановки.","Точні чинна й кандидатна редакції шаблону та перелік їх використань.","Дозволені контрольні дані й критерії змісту та вигляду результату.","Перевірені формати й можливості шаблонів у цільовому акаунті."],"limitations":["PlanFix документує шаблони Word і Excel та підстановку даних; керування редакціями й маршрут введення тут є проєктною моделлю.","Компоненти формування можуть змінювати форматування, особливо PDF. Вигляд вихідного шаблону не доводить вигляду створеного документа.","Юридично погоджений текст не підтверджує правильності змінних; контрольна генерація не замінює потрібного юридичного рішення.","Юридичну експертизу, масове переоформлення старих документів, власний редактор і готовий API-адаптер не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0031","reason":"Генерація окремого договору спирається на готовий шаблон; тут приймають і вводять змінену редакцію засобу генерації."},{"type":"related","target_id":"AUT-0032","reason":"Погодження файла не доводить правильної підстановки й вигляду сформованого результату."},{"type":"related","target_id":"AUT-0709","reason":"Сервісна форма збирає відповіді у завданні; шаблон формує вихідні документи з наявних даних."},{"type":"related","target_id":"AUT-0234","reason":"Ознайомлення працівників із текстом не перевіряє введення шаблону й фактичну генерацію."}],"configurator_questions":[{"id":"document-generation-template-revision-acceptance-formats","question":"Чи потрібно перевіряти кілька типів даних і вихідних форматів?","help_text":"Надайте контрольні випадки, потрібні формати та критерії змісту й вигляду документа.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Надайте контрольні випадки, потрібні формати та критерії змісту й вигляду документа."}]},{"id":"document-generation-template-revision-acceptance-usage","question":"Чи потрібна звірка кількох ручних або автоматичних місць генерації?","help_text":"Погодьте перелік використань, дату введення та докази фактично застосованої редакції.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте перелік використань, дату введення та докази фактично застосованої редакції."}]}]},{"schema_version":1,"id":"AUT-0776","slug":"product-vulnerability-coordinated-disclosure-control","title":"Координація погодженого розкриття вразливості продукту","summary":"Власник продукту узгоджує із залученими сторонами опрацювання повідомленої вразливості, конфіденційний період і фактичне розкриття погодженої інформації.","problem":"Повідомлення дослідника, технічне виправлення й дата публікації живуть у різних задачах. Готовність виправлення помилково вважають його розгортанням, а зміну дати не погоджують з учасниками.","outcome":"У справі видно підтверджені стани повідомлення, робіт і погодженого розкриття; приватні деталі не публікуються лише через загальний статус «готово».","category":"security-compliance","subcategory":"audit","roles":["operations-manager","owner","project-manager"],"industries":["cross-industry"],"triggers":["Команда продукту отримала повідомлення про можливу вразливість, яке потребує погодженої координації з дослідником або іншими сторонами."],"workflow_steps":["Зареєструвати повідомлення, продукт, версії й дозволені контакти; деталі та докази залишити в погодженій захищеній області.","Передати перевірку компетентному власнику; непідтверджене повідомлення, дублікат та підтверджену вразливість розрізняти без автоматичної публічної заяви.","Визначити залучені сторони та власників робіт; окремо зберігати факти обізнаності, готовності виправлення й доступності належного результату для споживачів.","Уповноважені сторони погоджують склад інформації й конфіденційний період до розкриття; пропозицію дати не видавати за прийняту домовленість.","Відстежувати підтверджені технічні результати й повідомлення сторін; зміну строків, новий продукт або порушення домовленості передати координатору на окреме рішення.","Перед розкриттям звірити чинне погодження, точну редакцію повідомлення та дозволених одержувачів; окремий технічний статус не запускає публікацію.","Зберегти підтвердження фактичного повідомлення й відкритий залишок робіт; публічна інформація не доводить виправлення всіх зачеплених інсталяцій."],"requirements":["Політика опрацювання повідомлень і дозволена конфіденційна комунікація.","Власник продукту, компетентний перевіряльник і координатор сторін.","Погоджені правила строків, перегляду домовленості та дозволу розкриття.","Авторитетні факти стану виправлень і точні редакції повідомлень."],"limitations":["SEI у публікації 2022 описує запропоновану модель координації, а не гарантовано реалізований протокол або універсальну правову вимогу.","Технічне підтвердження, пріоритет і дозволене розкриття визначають уповноважені фахівці; універсального строку очікування немає.","Публічна обізнаність, готовність виправлення та його фактичне розгортання — різні факти. Один статус задачі не підтверджує їх усі.","Тестування вразливостей, експлуатацію, розробку виправлень, винагороди дослідникам, правову експертизу та реальні публічні заяви не включено.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Повідомлення дослідника, технічне виправлення й дата публікації живуть у різних задачах. Готовність виправлення помилково вважають його розгортанням, а зміну дати не погоджують з учасниками."],"synonyms":["готовність виправлення сплутали з фактичним розгортанням","дату розкриття вразливості змінили без погодження сторін","загальний статус задачі помилково дозволив публікацію приватних деталей"],"search_queries":["як координувати погоджене розкриття вразливості продукту повідомлення сторін строк і стан виправлення"],"sources":[{"type":"research","url":"https://www.sei.cmu.edu/blog/vultron-a-protocol-for-coordinated-vulnerability-disclosure/","title":"SEI: модель координації повідомлень і розкриття вразливостей","checked_at":"2026-10-15","supports":"Прочитано 70–111: взаємодія повідомлення, конфіденційного періоду та станів справи; у статті зазначено статус пропозиції. Власні погодження, докази й години — модель для аудиту."},{"type":"inferred_pattern","title":"Редакційна модель погодження та звірки результату","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують продукти; конкретний акаунт, API-адаптер і клієнтський результат CRMCUSTOMS не перевірено."}],"status":"draft","variants":[{"id":"product-vulnerability-coordinated-disclosure-control-tracked","title":"Контроль із підтвердженням результату","description":"Власник продукту узгоджує із залученими сторонами опрацювання повідомленої вразливості, конфіденційний період і фактичне розкриття погодженої інформації.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Команда завершила підготовку виправлення, але поширення ще не підтвердили, а нову дату розкриття прийняла лише одна сторона. Координатор залишив ці факти окремими й повернув повідомлення на погодження.","implementation_methods":["Вести окремі підтвердження повідомлення, учасників, робіт, домовленості та дозволеної редакції розкриття.","Зіставляти дозволені результати сторін із чинною справою; повідомлення й публікацію передавати уповноваженим виконавцям."],"complexity":"medium","hours_min":28,"hours_max":56,"requirements":["Політика опрацювання повідомлень і дозволена конфіденційна комунікація.","Власник продукту, компетентний перевіряльник і координатор сторін.","Погоджені правила строків, перегляду домовленості та дозволу розкриття.","Авторитетні факти стану виправлень і точні редакції повідомлень."],"limitations":["SEI у публікації 2022 описує запропоновану модель координації, а не гарантовано реалізований протокол або універсальну правову вимогу.","Технічне підтвердження, пріоритет і дозволене розкриття визначають уповноважені фахівці; універсального строку очікування немає.","Публічна обізнаність, готовність виправлення та його фактичне розгортання — різні факти. Один статус задачі не підтверджує їх усі.","Тестування вразливостей, експлуатацію, розробку виправлень, винагороди дослідникам, правову експертизу та реальні публічні заяви не включено."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0089","reason":"Усунення підтвердженої вразливості ресурсу не погоджує між сторонами конфіденційний період і публічне розкриття."},{"type":"related","target_id":"AUT-0087","reason":"Реагування на інцидент безпеки не означає, що кожне повідомлення дослідника вже є інцидентом або дозволом розкриття."},{"type":"related","target_id":"AUT-0437","reason":"Запит коригувальної дії постачальнику не координує права й строки розкриття вразливості продукту."}],"configurator_questions":[{"id":"product-vulnerability-coordinated-disclosure-control-parties","question":"Чи потрібно погоджувати кілька сторін і змін конфіденційного періоду?","help_text":"Надайте ролі, правила домовленості, допустимі контакти та маршрут зміни строків.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Надайте ролі, правила домовленості, допустимі контакти та маршрут зміни строків."}]},{"id":"product-vulnerability-coordinated-disclosure-control-states","question":"Чи потрібна звірка окремих технічних станів і редакцій повідомлень?","help_text":"Погодьте джерела фактів, область продуктів, критерії розкриття й докази передавання.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":16,"add_hours_max":32,"assumption":"Погодьте джерела фактів, область продуктів, критерії розкриття й докази передавання."}]}]}];
